// Source: login.js
/**
 * Script for login.ejs
 */

// Login Elements
var loginCancelContainer  = document.getElementById('loginCancelContainer')
var loginCancelButton     = document.getElementById('loginCancelButton')
var loginEmailError       = document.getElementById('loginEmailError')
var loginUsername         = document.getElementById('loginUsername')
var checkmarkContainer    = document.getElementById('checkmarkContainer')
var loginRememberOption   = document.getElementById('loginRememberOption')
var loginButton           = document.getElementById('loginButton')
var loginForm             = document.getElementById('loginForm')

// Control variable.
var lu = false;
var isLoggingIn = false;

/**
 * Show a login error.
 * 
 * @param {HTMLElement} element The element on which to display the error.
 * @param {string} value The error text.
 */
function showError(element, value){
    element.innerHTML = value;
    element.style.opacity = 1;
}

/**
 * Shake a login error to add emphasis.
 * 
 * @param {HTMLElement} element The element to shake.
 */
function shakeError(element){
    if(element.style.opacity == 1){
        element.classList.remove('shake');
        void element.offsetWidth;
        element.classList.add('shake');
    }
}

/**
 * Validate that an email field is neither empty nor invalid.
 * 
 * @param {string} value The email value.
 */
function validateEmail(value) {
    var usernameRegex = /^[a-zA-Z0-9_]{3,16}$/;

    if (usernameRegex.test(value)) {
        loginEmailError.style.opacity = 0;
        lu = true;
    } else {
        showError(loginEmailError, Lang.queryJS('login.error.invalidValue'));
        lu = false;
    }

    checkLoginButtonEnabled(); 
}

function checkLoginButtonEnabled() {
    loginButton.disabled = !lu;
}

// Emphasize errors with shake when focus is lost.
loginUsername.addEventListener('focusout', (e) => {
    validateEmail(e.target.value);
    shakeError(loginEmailError);
});

// Validate input for email field.
loginUsername.addEventListener('input', (e) => {
    validateEmail(e.target.value);
});

/**
 * Enable or disable loading elements.
 * 
 * @param {boolean} v True to enable, false to disable.
 */
function loginLoading(v){
    if(v){
        loginButton.setAttribute('loading', v);
        loginButton.innerHTML = loginButton.innerHTML.replace(Lang.queryJS('login.login'), Lang.queryJS('login.loggingIn'));
    } else {
        loginButton.removeAttribute('loading');
        loginButton.innerHTML = loginButton.innerHTML.replace(Lang.queryJS('login.loggingIn'), Lang.queryJS('login.login'));
    }
}

/**
 * Enable or disable login form.
 * 
 * @param {boolean} v True to enable, false to disable.
 */
function formDisabled(v){
    loginCancelButton.disabled = v;
    loginUsername.disabled = v;
    if(v){
        checkmarkContainer.setAttribute('disabled', v);
    } else {
        checkmarkContainer.removeAttribute('disabled');
    }
    loginRememberOption.disabled = v;
}

var loginViewOnSuccess = VIEWS.landing;
var loginViewOnCancel = VIEWS.settings;
var loginViewCancelHandler;

function loginCancelEnabled(val){
    if(val){
        $(loginCancelContainer).show();
    } else {
        $(loginCancelContainer).hide();
    }
}

loginCancelButton.onclick = (e) => {
    switchView(getCurrentView(), loginViewOnCancel, 500, 500, () => {
        loginUsername.value = '';
        loginCancelEnabled(false);
        if(loginViewCancelHandler != null){
            loginViewCancelHandler();
            loginViewCancelHandler = null;
        }
    });
};

// Disable default form behavior.
loginForm.onsubmit = () => { return false; };

// Bind login button behavior.
loginButton.addEventListener('click', async () => {

    if (isLoggingIn) return;
    isLoggingIn = true;

    formDisabled(true);
    loginLoading(true);

    try {
        const value = await AuthManager.addAccount(loginUsername.value);

        updateSelectedAccount(value);

        loginButton.innerHTML = loginButton.innerHTML.replace(
            Lang.queryJS('login.loggingIn'),
            Lang.queryJS('login.success')
        );

        $('.circle-loader').toggleClass('load-complete');
        $('.checkmark').toggle();

        setTimeout(async () => {

            await switchView(VIEWS.login, loginViewOnSuccess, 500, 500, async () => {

                if (loginViewOnSuccess === VIEWS.settings) {
                    await prepareSettings();
                }

                loginViewOnSuccess = VIEWS.landing;
                loginCancelEnabled(false);
                loginViewCancelHandler = null;
                loginUsername.value = '';

                $('.circle-loader').toggleClass('load-complete');
                $('.checkmark').toggle();

                loginLoading(false);
                loginButton.innerHTML = loginButton.innerHTML.replace(
                    Lang.queryJS('login.success'),
                    Lang.queryJS('login.login')
                );

                isLoggingIn = false;
                formDisabled(false);
                lu = false;
                checkLoginButtonEnabled();
            });

        }, 1000);

    } catch (displayableError) {

        isLoggingIn = false;
        loginLoading(false);

        let actualDisplayableError;

        if (isDisplayableError(displayableError)) {
            msftLoginLogger.error('Error while logging in.', displayableError);
            actualDisplayableError = displayableError;
        } else {
            console.log("FULL LOGIN ERROR:", displayableError);
            console.log("STRINGIFIED:", JSON.stringify(displayableError, null, 2));
            actualDisplayableError = Lang.queryJS('login.error.unknown');
        }

        setOverlayContent(
            actualDisplayableError.title,
            actualDisplayableError.desc,
            Lang.queryJS('login.tryAgain')
        );

        setOverlayHandler(() => {
            formDisabled(false);
            toggleOverlay(false);
            lu = false;
            checkLoginButtonEnabled();
        });

        toggleOverlay(true);
    }
});


