//Languages
var langCodes = {
    "es_ES": "Español",
    "en_US": "English",
    "pt_BR": "Portugues-BR",
} 

async function resolveLanguageForUI() {
    ConfigManager.getAllLanguages((err, languages) => {
        if (err) {
            console.error("Error al cargar idiomas:", err);
            return;
        }
        
        const selected = ConfigManager.getCurrentLanguage();
        
        // Intentamos inicializar la UI
        // Si no está lista, lo intentamos en 100ms
        const interval = setInterval(() => {
            if (document.getElementById('settingsLangsOptions')) {
                clearInterval(interval);
                setCurrentLanguageInUi(languages, selected);
            }
        }, 100);
    });
}

function setCurrentLanguageInUi(arr, selected) {
    const cont = document.getElementById('settingsLangsOptions');
    const selectedDisplay = document.getElementById('settingsLangSelected');

    // Validación de seguridad
    if (!cont || !selectedDisplay) return;

    cont.innerHTML = '';
    
    for (let opt of arr) {
        // Usamos langCodes[opt] si existe, si no, usamos el nombre del código
        const label = langCodes[opt] || opt;
        
        const d = document.createElement('DIV');
        d.innerHTML = label;
        d.setAttribute('value', opt);
        
        if (opt !== "_custom") {
            if (opt === selected) {
                d.setAttribute('selected', '');
                selectedDisplay.innerHTML = label;
            }
            d.addEventListener('click', function(e) {
                // Actualizamos el display visual
                selectedDisplay.innerHTML = this.innerHTML;
                
                // Limpiamos selección anterior
                for (let sib of this.parentNode.children) {
                    sib.removeAttribute('selected');
                }
                this.setAttribute('selected', '');
                
                if (typeof closeSettingsSelect === 'function') closeSettingsSelect();
                ConfigManager.setLanguage(opt);
            });
            cont.appendChild(d);
        }
    }
}

// Shaderpack

var CACHE_SETTINGS_INSTANCE_DIR
var CACHE_SHADERPACKS
var CACHE_SELECTED_SHADERPACK

/**
 * Load shaderpack information.
 */
async function resolveShaderpacksForUI(){
    const serv = (await DistroAPI.getDistribution()).getServerById(ConfigManager.getSelectedServer())
    CACHE_SETTINGS_INSTANCE_DIR = path.join(ConfigManager.getInstanceDirectory(), serv.rawServer.id)
    CACHE_SHADERPACKS = DropinModUtil.scanForShaderpacks(CACHE_SETTINGS_INSTANCE_DIR)
    CACHE_SELECTED_SHADERPACK = DropinModUtil.getEnabledShaderpack(CACHE_SETTINGS_INSTANCE_DIR)

    setShadersOptions(CACHE_SHADERPACKS, CACHE_SELECTED_SHADERPACK)
}

function setShadersOptions(arr, selected){
    const cont = document.getElementById('settingsShadersOptions')
    cont.innerHTML = ''
    for(let opt of arr) {
        const d = document.createElement('DIV')
        d.innerHTML = opt.name
        d.setAttribute('value', opt.fullName)
        if(opt.fullName === selected) {
            d.setAttribute('selected', '')
            document.getElementById('settingsShadersSelected').innerHTML = opt.name
        }
        d.addEventListener('click', function(e) {
            this.parentNode.previousElementSibling.innerHTML = this.innerHTML
            for(let sib of this.parentNode.children){
                sib.removeAttribute('selected')
            }
            this.setAttribute('selected', '')
            closeSettingsSelect()
        })
        cont.appendChild(d)
    }
}

function saveShaderpackSettings(){
    let sel = 'OFF'
    for(let opt of document.getElementById('settingsShadersOptions').childNodes){
        if(opt.hasAttribute('selected')){
            sel = opt.getAttribute('value')
        }
    }
    DropinModUtil.setEnabledShaderpack(CACHE_SETTINGS_INSTANCE_DIR, sel)
}

function bindShaderpackButton() {
    const spBtn = document.getElementById('settingsShaderpackButton')
    spBtn.onclick = () => {
        const p = path.join(CACHE_SETTINGS_INSTANCE_DIR, 'shaderpacks')
        DropinModUtil.validateDir(p)
        shell.openPath(p)
    }
    spBtn.ondragenter = e => {
        e.dataTransfer.dropEffect = 'move'
        spBtn.setAttribute('drag', '')
        e.preventDefault()
    }
    spBtn.ondragover = e => {
        e.preventDefault()
    }
    spBtn.ondragleave = e => {
        spBtn.removeAttribute('drag')
    }

    spBtn.ondrop = async e => {
        spBtn.removeAttribute('drag')
        e.preventDefault()

        DropinModUtil.addShaderpacks(e.dataTransfer.files, CACHE_SETTINGS_INSTANCE_DIR)
        saveShaderpackSettings()
        await resolveShaderpacksForUI()
    }
}

